def repair(values, n):
    if n <= 0:
        raise ValueError('positive size required')
    return [values[i:i+n] for i in range(0, len(values), n)]

py-unicode.content:
import unicodedata

def repair(values):
    groups = {}
    for value in values:
        key = unicodedata.normalize('NFC', value).casefold()
        groups.setdefault(key, []).append(value)
    return groups

